#!/usr/bin/env node

/**
 * show-dirs-files-tree.js — Display directory/file tree from Dirs-Tree.json
 *
 * Reads the Dirs-Tree.json generated by boundify and displays nodeId, title,
 * and kind mapped to each file in tree format.
 *
 * CLI: show-dirs-files-tree.js </path/to/RFC-ROOT-Dirs-Tree.json>
 *      show-dirs-files-tree.js --doc=</path/to/RFC-ROOT.md>
 *
 * The --doc form derives the Dirs-Tree from the RFC by the pipeline's naming rule.
 *
 * Exit codes:
 *   0  Success
 *   1  Error
 */

const fs = require("fs");
const path = require("path");

const { deriveDirsTreePathFromDoc } = require("../lib/package-artifacts");
const {
  resolveDirsTreePath: resolveCanonicalDirsTreePath,
  reportResolvedPath,
} = require("../lib/package-artifacts");
const { writeLine } = require("../lib/cli-output");

const EXIT_SUCCESS = 0;
const EXIT_FAILURE = 1;

/**
 * Resolve the Dirs-Tree path from the CLI arguments.
 *
 * `--doc=<RFC>` derives it; a positional `.md` does the same; any other positional
 * is taken as the Dirs-Tree itself so the pre-existing form keeps working.
 *
 * @param {string[]} args — process.argv.slice(2)
 * @returns {string|null}
 */
// [::TICKET::] PX-334 changes. Details: `node .claude/scripts/tickets/show-ticket-context.js --ticket-key=PX-334 --for-spec --no-implementation-order`.
function resolveDirsTreePath(args, options = {}) {
  const cwd = options.cwd || process.cwd();
  const docArgument = args.find(function (arg) { return arg.startsWith("--doc="); });
  if (docArgument) {
    return deriveDirsTreePathFromDoc(path.resolve(cwd, docArgument.slice("--doc=".length)));
  }
  const positional = args.filter(function (arg) { return !arg.startsWith("--"); });
  if (positional.length === 0) {
    const derived = resolveCanonicalDirsTreePath({ cwd });
    reportResolvedPath("dirs-tree", derived);
    return derived;
  }
  if (positional[0].endsWith(".md")) {
    return deriveDirsTreePathFromDoc(path.resolve(cwd, positional[0]));
  }
  return path.resolve(cwd, positional[0]);
}

/**
 * Outputs error to stderr using 3-segment template and exits with code 1
 */
function exitWithError(message, cause, action) {
  process.stderr.write("[ERROR] " + message + "\n");
  process.stderr.write("Cause: " + cause + "\n");
  process.stderr.write("Action: " + action + "\n");
  process.exit(EXIT_FAILURE);
}

/**
 * Outputs tree recursively in Markdown nested list format
 *
 * @param {object[]} nodes - DirNode array
 * @param {number} depth - Current indent depth (0-based)
 * @param {string[]} lines - Line accumulation array (mutative append)
 */
function renderTree(nodes, depth, lines) {
  const indent = "    ".repeat(depth);
  for (const node of nodes) {
    if (node.type === "directory") {
      const kindLabel = node.kind && node.kind !== "root" ? " [" + node.kind + "]" : "";
      lines.push(indent + "- " + node.name + "/" + kindLabel);
      if (node.children) {
        renderTree(node.children, depth + 1, lines);
      }
    } else if (node.type === "file") {
      const ids = node.mappedNodeIds || [];
      if (ids.length > 0) {
        const annotations = ids.map(function (e) {
          const nid = e.nodeId || "";
          const title = e.title || "";
          const kind = node.kind || "";
          return "(" + nid + ": " + title + " [" + kind + "])";
        });
        lines.push(indent + "- " + node.name + " " + annotations.join(" "));
      } else {
        lines.push(indent + "- " + node.name);
      }
    }
  }
}

/**
 * Main entry point
 */
// [::TICKET::] PX-334, PX-341 changes. Details: `node "$(git rev-parse --show-toplevel)/.claude/scripts/tickets/show-ticket-context.js" --ticket-key=(PX-334|PX-341) --for-spec --no-implementation-order`.
function main() {
  const args = process.argv.slice(2);

  if (args[0] === "--help" || args[0] === "-h") {
    writeLine("show-dirs-files-tree.js — Display directory/file tree from Dirs-Tree.json");
    writeLine("");
    writeLine("Usage:");
    writeLine("  show-dirs-files-tree.js");
    writeLine("  show-dirs-files-tree.js </path/to/RFC-ROOT-Dirs-Tree.json>");
    writeLine("  show-dirs-files-tree.js --doc=</path/to/RFC-ROOT.md>");
    writeLine("");
    writeLine("Options:");
    writeLine("  (no argument)  Read ./RFC-Dirs-Tree.json beside ./RFC-GRAPH.json");
    writeLine("  --doc=<RFC>  Derive the Dirs-Tree from the RFC path");
    writeLine("  --help, -h  Show this help");
    process.exit(EXIT_SUCCESS);
  }

  const dirsTreePath = resolveDirsTreePath(args);
  if (!dirsTreePath || !fs.existsSync(dirsTreePath)) {
    exitWithError(
      "Dirs-Tree.json not found: " + dirsTreePath,
      "File does not exist at the specified path.",
      "Specify the correct path."
    );
  }

  let dirsTree;
  try {
    dirsTree = JSON.parse(fs.readFileSync(dirsTreePath, "utf8"));
  } catch (e) {
    exitWithError(
      "Dirs-Tree.json parse failed: " + e.message,
      "Verify the file is valid JSON format.",
      "Specify a correct Dirs-Tree.json file."
    );
  }

  const graphFileName = path.basename(dirsTree.sourceGraph || "");
  const sourceFileName = path.basename(dirsTree.sourceFile || "");
  const dirsTreeFileName = path.basename(dirsTreePath);

  writeLine("# Directory / File Structure — Mapped Nodes");
  writeLine("");

  const langKeys = Object.keys(dirsTree.trees || {});
  const langInfo = langKeys.join(", ");
  writeLine(
    "Language: " + langInfo + " | Graph: " + graphFileName + " | Source: " + sourceFileName
  );
  writeLine("");

  writeLine("## To show node details");
  writeLine("");
  writeLine("```");
  writeLine(
    'node "$(git rev-parse --show-toplevel)/.claude/scripts/rfc-graph/query.js" --graph="' +
      graphFileName +
      '" --source="' +
      sourceFileName +
      '" --dirs-tree="' +
      dirsTreeFileName +
      '" --id=Nxxxx (e.g. N0001) --hops=<N> (1=direct, 2+=includes grandchildren)'
  );
  writeLine("```");
  writeLine("");

  const trees = dirsTree.trees || {};
  for (const lang of langKeys) {
    const root = trees[lang];
    if (!root) continue;

    writeLine("## " + lang.charAt(0).toUpperCase() + lang.slice(1));
    writeLine("");

    const kindLabel = root.kind && root.kind !== "root" ? " [" + root.kind + "]" : " [source-root]";
    writeLine("- " + root.name + "/" + kindLabel);

    if (root.children) {
      var treeLines = [];
      renderTree(root.children, 1, treeLines);
      for (var ti = 0; ti < treeLines.length; ti++) {
        writeLine(treeLines[ti]);
      }
      writeLine("");
    }
  }
}

if (require.main === module) {
  main();
}

module.exports = { renderTree, resolveDirsTreePath };
